import type { ImageLoaderProps } from "next/image";

/** Widths generated by Payload for Media uploads (`payload/collections/Media.ts`). */
const VARIANT_WIDTHS = [640, 1280, 1920] as const;
const MEDIA_FILE_RE = /^\/api\/media\/file\/([^/?#]+)\.(?:jpe?g|png|webp|avif)$/i;

function extractPathname(src: string): string | null {
  if (src.startsWith("/")) {
    return src;
  }
  if (/^https?:\/\//i.test(src)) {
    try {
      const url = new URL(src);
      return url.search || url.hash ? null : url.pathname;
    } catch {
      return null;
    }
  }
  return null;
}

/**
 * Serves Payload's pre-generated WebP variants (`-w640`, `-w1280`, `-w1920`) for
 * CMS media paths without going through Vercel's `/_next/image` optimizer.
 */
export default function imageLoader({ src, width }: ImageLoaderProps): string {
  const pathname = extractPathname(src);
  if (!pathname) return src;

  const match = MEDIA_FILE_RE.exec(pathname);
  if (!match) return src;

  const variantWidth = VARIANT_WIDTHS.find((candidate) => candidate >= width) ?? 1920;
  return `/api/media/file/${match[1]}-w${variantWidth}.webp`;
}
